  "No row is changed by inspection.": { sw: "Hakuna safu inayobadilishwa kwa ukaguzi.", fr: "Aucune ligne n’est modifiée par l’inspection.", es: "Ninguna fila se modifica al inspeccionar.", pt: "Nenhuma linha é alterada pela inspeção.", zh: "检查不会更改任何行。", ar: "لا يتم تغيير أي صف عند الفحص.", de: "Durch die Prüfung wird keine Zeile geändert.", hi: "निरीक्षण से कोई पंक्ति नहीं बदलती।", ja: "検査によって行は変更されません。" },
