  "Enter a valid Tanzania mobile number.": { sw: "Weka namba halali ya simu ya Tanzania.", fr: "Saisissez un numéro mobile tanzanien valide.", es: "Introduce un número móvil tanzano válido.", pt: "Introduza um número móvel tanzaniano válido.", zh: "请输入有效的坦桑尼亚手机号码。", ar: "أدخل رقم هاتف محمول تنزاني صالح.", de: "Geben Sie eine gültige tansanische Mobilnummer ein.", hi: "मान्य तंज़ानिया मोबाइल नंबर दर्ज करें।", ja: "有効なタンザニアの携帯番号を入力してください。" },
  "Sending request": { sw: "Inatuma ombi", fr: "Envoi de la demande", es: "Enviando solicitud", pt: "A enviar pedido", zh: "正在发送请求", ar: "جارٍ إرسال الطلب", de: "Anfrage wird gesendet", hi: "अनुरोध भेजा जा रहा है", ja: "リクエストを送信中" },
