  "Official global package": { sw: "Kifurushi rasmi cha kimataifa", fr: "Forfait mondial officiel", es: "Paquete global oficial", pt: "Pacote global oficial", zh: "官方全球套餐", ar: "حزمة عالمية رسمية", de: "Offizielles globales Paket", hi: "आधिकारिक वैश्विक पैकेज", ja: "公式グローバルパッケージ" },
  "Subscription billing receipt": { sw: "Risiti ya malipo ya usajili", fr: "Reçu de facturation d’abonnement", es: "Recibo de facturación de suscripción", pt: "Recibo de faturação de subscrição", zh: "订阅账单收据", ar: "إيصال فوترة الاشتراك", de: "Abrechnungsbeleg für Abonnement", hi: "सदस्यता बिलिंग रसीद", ja: "サブスクリプション請求領収書" },
