  "This receipt reflects a server-verified subscription payment.": { sw: "Risiti hii inaonyesha malipo ya usajili yaliyothibitishwa na seva.", fr: "Ce reçu reflète un paiement d’abonnement vérifié par le serveur.", es: "Este recibo refleja un pago de suscripción verificado por el servidor.", pt: "Este recibo reflete um pagamento de subscrição verificado pelo servidor.", zh: "此收据反映经服务器验证的订阅付款。", ar: "يعكس هذا الإيصال دفعة اشتراك موثّقة من الخادم.", de: "Dieser Beleg spiegelt eine serververifizierte Abonnementzahlung wider.", hi: "यह रसीद सर्वर-सत्यापित सदस्यता भुगतान दर्शाती है।", ja: "この領収書はサーバーで検証されたサブスクリプション支払いを反映しています。" },
