  "No subscription payments yet": { sw: "Hakuna malipo ya usajili bado", fr: "Aucun paiement d’abonnement pour l’instant", es: "Aún no hay pagos de suscripción", pt: "Ainda não há pagamentos de subscrição", zh: "暂无订阅付款", ar: "لا توجد مدفوعات اشتراك بعد", de: "Noch keine Abonnementzahlungen", hi: "अभी तक कोई सदस्यता भुगतान नहीं", ja: "サブスクリプション支払いはまだありません" },
  "No subscription invoices yet": { sw: "Hakuna ankara za usajili bado", fr: "Aucune facture d’abonnement pour l’instant", es: "Aún no hay facturas de suscripción", pt: "Ainda não há faturas de subscrição", zh: "暂无订阅发票", ar: "لا توجد فواتير اشتراك بعد", de: "Noch keine Abonnementrechnungen", hi: "अभी तक कोई सदस्यता इनवॉइस नहीं", ja: "サブスクリプション請求書はまだありません" },
