  "Billing information": { sw: "Maelezo ya malipo", fr: "Informations de facturation", es: "Información de facturación", pt: "Informações de faturação", zh: "账单信息", ar: "معلومات الفوترة", de: "Rechnungsinformationen", hi: "बिलिंग जानकारी", ja: "請求情報" },
  "This company-scoped information appears on subscription invoices and receipts.": { sw: "Maelezo haya ya kampuni yanaonekana kwenye ankara na risiti za usajili.", fr: "Ces informations propres à l’entreprise apparaissent sur les factures et reçus d’abonnement.", es: "Esta información propia de la empresa aparece en las facturas y recibos de suscripción.", pt: "Esta informação própria da empresa aparece nas faturas e recibos de subscrição.", zh: "此公司范围内的信息会出现在订阅发票和收据上。", ar: "تظهر هذه المعلومات الخاصة بالشركة على فواتير وإيصالات الاشتراك.", de: "Diese unternehmensbezogenen Informationen erscheinen auf Abonnementrechnungen und -belegen.", hi: "यह कंपनी-विशिष्ट जानकारी सदस्यता इनवॉइस और रसीदों पर दिखती है।", ja: "この企業固有の情報は、サブスクリプション請求書と領収書に表示されます。" },
  Popular: { sw: "Maarufu", fr: "Populaire", es: "Popular", pt: "Popular", zh: "热门", ar: "شائع", de: "Beliebt", hi: "लोकप्रिय", ja: "人気" },
